func TestProbeRegistryOnlyRemovedUpstream(t *testing.T) {
	a1, a2 := net.Pipe()
	b1, b2 := net.Pipe()
	defer a2.Close()
	defer b2.Close()
	sa := &detachedStream{conns: []openConnection{{conn: a1}}, stats: newStreamStats("pa", nil, zapcore.DebugLevel)}
